import React, { useState } from "react";
import { useNavigate, Link } from "react-router-dom";

function Login() {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    email: "",
    password: ""
  });

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    
    // Simulation des données utilisateur selon l'email
    let userData;
    
    if (formData.email.includes("etudiant") || formData.email.includes("student")) {
      // Données étudiant
      userData = {
        id: 2,
        nom: "Étudiant Test",
        email: formData.email,
        role: "student",
      };
    } else if (formData.email.includes("prof") || formData.email.includes("teacher")) {
      // Données professeur
      userData = {
        id: 1,
        nom: "Professeur Test",
        email: formData.email,
        role: "prof",
      };
    } else {
      // Utilisateur par défaut (étudiant)
      userData = {
        id: 3,
        nom: "Utilisateur Test",
        email: formData.email,
        role: "student",
        classe: "Classe par défaut",
        niveau: "N/A",
        numero_etudiant: "ETU000000"
      };
    }

    // Sauvegarder les infos utilisateur dans localStorage
    localStorage.setItem('user', JSON.stringify(userData));
    localStorage.setItem('isAuthenticated', 'true');
    localStorage.setItem('userRole', userData.role);

    console.log("Login data:", formData);
    console.log("User data saved:", userData);
    
    alert(`Connexion réussie! Rôle: ${userData.role}`);
    
    // Redirection selon le rôle
    if (userData.role === "prof") {
      navigate("/dashboard-prof");
    } else if (userData.role === "student") {
      navigate("/dashboard-student");
    } else {
      navigate("/dashboard");
    }
  };

  return (
    <div className="auth-container">
      <div className="auth-card">
        <div className="auth-header">
          <div className="logo">
            <i className="fas fa-graduation-cap"></i>
            <span>Gestion Cours</span>
          </div>
          <h2>Connexion</h2>
          <p>Connectez-vous à votre compte</p>
        </div>

        <form onSubmit={handleSubmit} className="auth-form">
          <div className="form-group">
            <label htmlFor="email">Email</label>
            <input
              type="email"
              id="email"
              name="email"
              value={formData.email}
              onChange={handleChange}
              required
              placeholder="votre@email.com"
            />
          </div>

          <div className="form-group">
            <label htmlFor="password">Mot de passe</label>
            <input
              type="password"
              id="password"
              name="password"
              value={formData.password}
              onChange={handleChange}
              required
              placeholder="Votre mot de passe"
            />
          </div>


          <div className="form-options">
            <label className="checkbox">
              <input type="checkbox" />
              Se souvenir de moi
            </label>
            <a href="#" className="forgot-password">Mot de passe oublié ?</a>
          </div>

          <button type="submit" className="btn btn-primary btn-full">
            Se connecter
          </button>
        </form>

        <div className="auth-footer">
          <p>
            Pas de compte ? <Link to="/register">Créer un compte</Link>
          </p>
        </div>
      </div>
    </div>
  );
}
        
export default Login;
